/*
 * Corpus-driven tests of lib/fimg (vectors generated by gen_vectors.py).
 *
 * Every image is decoded with several input chunkings (whole file, 1 byte,
 * a prime-size cycle, 64-byte USB packets, pseudo-random sizes); all of them
 * must agree bit for bit (status, info, luma, bitmap). Depending on the
 * manifest entry the test then checks the status, the full-resolution luma
 * against a reference (exact for PNG, +-2 for JPEG), the luma CRC, or the
 * binarized bitmap of a QR render (pixel agreement with a fixed threshold on
 * the box-downscaled luma, and module-centre agreement with the QR matrix).
 * Raw zlib streams exercise the inflater directly.
 */
#include <time.h>

#include "fimg.h"
#include "fimg_internal.h"
#include "test_util.h"

#ifndef FIMG_VECTORS_DIR
#define FIMG_VECTORS_DIR "vectors"
#endif

#define NPATTERNS 5

typedef struct {
  fimg_status_t st;
  fimg_info_t info;
  uint8_t *luma; /* FIMG_MAX_DIM^2 */
  uint32_t luma_w, rows_seen;
  int luma_order_bad;
  uint8_t *bitmap;
  size_t bitmap_size;
  uint32_t bm_crc, luma_crc;
} result_t;

static void luma_cb(void *user, uint32_t y, const uint8_t *row, uint32_t w) {
  result_t *r = (result_t *)user;
  if (y != r->rows_seen || w > FIMG_MAX_DIM || y >= FIMG_MAX_DIM) {
    r->luma_order_bad = 1;
    return;
  }
  memcpy(r->luma + (size_t)y * w, row, w);
  r->luma_w = w;
  r->rows_seen++;
}

static size_t next_chunk(int pattern, uint32_t *rs, size_t idx) {
  static const size_t primes[] = {7, 13, 251, 4093, 3, 1, 509};
  switch (pattern) {
    case 0:
      return (size_t)-1;
    case 1:
      return 1;
    case 2:
      return primes[idx % (sizeof primes / sizeof primes[0])];
    case 3:
      return 64;
    default:
      return 1u + test_rand(rs) % 700u;
  }
}

static void decode(const uint8_t *data, size_t len, int pattern,
                   const fimg_config_t *cfg_in, result_t *r, int scattered) {
  fimg_config_t cfg = *cfg_in;
  size_t wsz = fimg_workspace_size(&cfg), off = 0, idx = 0;
  uint8_t *ws = NULL;
  uint8_t *allocations[FIMG_SCATTERED_MAX_BLOCKS] = {0};
  size_t sizes[FIMG_SCATTERED_MAX_BLOCKS];
  fimg_block_t blocks[FIMG_SCATTERED_MAX_BLOCKS];
  size_t count = 0;
  fimg_ctx_t *ctx = NULL;
  uint32_t rs = 0x12345u + (uint32_t)len;
  fimg_status_t st;

  memset(r, 0, sizeof *r);
  r->luma = (uint8_t *)calloc((size_t)FIMG_MAX_DIM * FIMG_MAX_DIM, 1);
  r->bitmap_size = fimg_bitmap_size(&cfg);
  r->bitmap = (uint8_t *)malloc(r->bitmap_size);
  memset(r->bitmap, 0xa5, r->bitmap_size);
  cfg.luma_cb = luma_cb;
  cfg.luma_cb_user = r;
  if (scattered) {
    count = fimg_scattered_sizes(&cfg, sizes, FIMG_SCATTERED_MAX_BLOCKS);
    CHECK(count > 0 && count <= FIMG_SCATTERED_MAX_BLOCKS);
    for (size_t i = 0; i < count; i++) {
      CHECK(sizes[i] > 0 && sizes[i] <= FIMG_SCATTERED_BLOCK_MAX);
      allocations[i] = (uint8_t *)malloc(sizes[i] + 32);
      CHECK(allocations[i] != NULL);
      if (allocations[i] == NULL) exit(2);
      memset(allocations[i], 0xd3, sizes[i] + 32);
      blocks[i].ptr = allocations[i] + 16;
      blocks[i].size = sizes[i];
    }
    st = fimg_init_scattered(&ctx, blocks, count, &cfg, r->bitmap,
                             r->bitmap_size);
  } else {
    ws = (uint8_t *)malloc(wsz + 16);
    CHECK(ws != NULL);
    if (ws == NULL) exit(2);
    /* deliberately misaligned contiguous workspace */
    st = fimg_init(&ctx, ws + 3, wsz, &cfg, r->bitmap, r->bitmap_size);
  }
  CHECK(st == FIMG_OK);
  if (st != FIMG_OK) {
    r->st = st;
    goto done;
  }
  while (off < len) {
    size_t n = next_chunk(pattern, &rs, idx++);
    if (n > len - off) n = len - off;
    st = fimg_feed(ctx, data + off, n);
    off += n;
    if (st != FIMG_OK) break;
  }
  if (st == FIMG_OK) CHECK(fimg_feed(ctx, data, 0) == FIMG_OK);
  r->st = fimg_finish(ctx, &r->info);
  CHECK(fimg_feed(ctx, data, 1) == (r->st == FIMG_OK ? FIMG_E_STATE : r->st));
  if (r->st == FIMG_OK) {
    CHECK(r->info.complete);
    r->bm_crc = test_crc32(r->bitmap, r->info.stride * r->info.out_height);
    r->luma_crc =
        test_crc32(r->luma, (size_t)r->info.src_width * r->info.src_height);
    CHECK(r->rows_seen == r->info.src_height);
    CHECK(!r->luma_order_bad);
    /* padding bits beyond out_width are zero */
    if (r->info.out_width % 8u) {
      uint8_t mask = (uint8_t)(0xffu >> (r->info.out_width % 8u));
      for (uint32_t y = 0; y < r->info.out_height; y++)
        CHECK(!(r->bitmap[y * r->info.stride + r->info.stride - 1] & mask));
    }
  }
done:
  if (ws != NULL) {
    fimg_secure_zero(ws, wsz + 16);
    free(ws);
  }
  for (size_t i = 0; i < count; i++) {
    for (size_t j = 0; j < 16; j++) {
      CHECK(allocations[i][j] == 0xd3);
      CHECK(allocations[i][16 + sizes[i] + j] == 0xd3);
    }
    fimg_secure_zero(allocations[i], sizes[i] + 32);
    free(allocations[i]);
  }
}

static void free_result(result_t *r) {
  free(r->luma);
  free(r->bitmap);
}

static int status_from_name(const char *name) {
  for (int i = 0; i < FIMG_STATUS_COUNT; i++)
    if (strcmp(fimg_status_name((fimg_status_t)i), name) == 0) return i;
  return -1;
}

static uint8_t *read_pgm(const char *path, uint32_t *w, uint32_t *h) {
  size_t len;
  uint8_t *f = read_file(path, &len), *pix;
  unsigned ww, hh, mx;
  int consumed = 0;
  if (f == NULL) return NULL;
  f[len] = 0;
  if (sscanf((const char *)f, "P5 %u %u %u%n", &ww, &hh, &mx, &consumed) != 3 ||
      mx != 255) {
    free(f);
    return NULL;
  }
  consumed++; /* single whitespace */
  if ((size_t)consumed + (size_t)ww * hh > len) {
    free(f);
    return NULL;
  }
  pix = (uint8_t *)malloc((size_t)ww * hh);
  memcpy(pix, f + consumed, (size_t)ww * hh);
  free(f);
  *w = ww;
  *h = hh;
  return pix;
}

static double g_time_jpeg_1024, g_time_png_1024;

/* Decode @p name with every chunking; all results must be identical. */
static int decode_all(const char *name, const uint8_t *data, size_t len,
                      const fimg_config_t *cfg, result_t *out) {
  result_t r;
  int ok = 1;
  for (int p = 0; p < NPATTERNS; p++) {
    clock_t t0 = clock();
    result_t segmented;
    result_t *contiguous = p == 0 ? out : &r;
    decode(data, len, p, cfg, contiguous, 0);
    decode(data, len, p, cfg, &segmented, 1);
    /* Same input and chunking must agree, including partially decoded
       images and bytes produced before an input error. */
    CHECK_MSG(
        segmented.st == contiguous->st &&
            memcmp(&segmented.info, &contiguous->info, sizeof segmented.info) ==
                0 &&
            segmented.rows_seen == contiguous->rows_seen &&
            segmented.luma_w == contiguous->luma_w &&
            segmented.luma_order_bad == contiguous->luma_order_bad &&
            memcmp(segmented.luma, contiguous->luma,
                   (size_t)FIMG_MAX_DIM * FIMG_MAX_DIM) == 0 &&
            segmented.bitmap_size == contiguous->bitmap_size &&
            memcmp(segmented.bitmap, contiguous->bitmap,
                   segmented.bitmap_size) == 0,
        "%s: scattered differs for chunking %d cfg%ux%u: st%d/%d "
        "info%d luma%d bitmap%d rows%u/%u",
        name, p, cfg->max_out_width, cfg->max_out_height, segmented.st,
        contiguous->st,
        memcmp(&segmented.info, &contiguous->info, sizeof segmented.info),
        memcmp(segmented.luma, contiguous->luma,
               (size_t)FIMG_MAX_DIM * FIMG_MAX_DIM),
        memcmp(segmented.bitmap, contiguous->bitmap, segmented.bitmap_size),
        segmented.rows_seen, contiguous->rows_seen);
    free_result(&segmented);
    if (p == 0) {
      double dt = (double)(clock() - t0) / CLOCKS_PER_SEC;
      if (strcmp(name, "qr_backup_1024_q70.jpg") == 0) g_time_jpeg_1024 = dt;
      if (strcmp(name, "qr_backup_1024.png") == 0) g_time_png_1024 = dt;
      continue;
    }
    /* errors: same status (bytes_consumed may differ with the chunking) */
    if (r.st != out->st ||
        (r.st == FIMG_OK &&
         (r.bm_crc != out->bm_crc || r.luma_crc != out->luma_crc ||
          memcmp(&r.info, &out->info, sizeof r.info) != 0))) {
      fprintf(stderr, "%s: chunking %d differs (status %s vs %s)\n", name, p,
              fimg_status_name(r.st), fimg_status_name(out->st));
      ok = 0;
    }
    free_result(&r);
  }
  CHECK_MSG(ok, "%s", name);
  return ok;
}

static void run_zlib(const char *dir, const char *file, const char *kind,
                     const char *a1, const char *a2) {
  char path[512];
  size_t len;
  uint8_t *data;
  static uint8_t win[FIMG_INF_WSIZE];
  static uint8_t paged[2][FIMG_INF_PAGE_SIZE + 32];
  static uint8_t small[16][4096 + 32];
  static fimg_inflate_t inf;
  snprintf(path, sizeof path, "%s/%s", dir, file);
  data = read_file(path, &len);
  CHECK_MSG(data != NULL, "%s", path);
  if (data == NULL) return;
  for (int mode = 0; mode < 4; mode++) {
    for (int p = 0; p < NPATTERNS; p++) {
      size_t off = 0, idx = 0;
      uint32_t rs = 99, crc = 0xffffffffu, total = 0;
      fimg_inf_result_t r = FIMG_INF_NEED_INPUT;
      if (mode == 0) {
        fimg_inflate_init(&inf, win);
      } else if (mode == 1) {
        memset(paged, 0xd3, sizeof paged);
        fimg_inflate_init_paged(&inf, paged[0] + 16, paged[1] + 16);
      } else {
        uint8_t *pages[16];
        uint32_t page_size =
            mode == 2
                ? 2048u
                : (mode == 3 ? 4096u
                             : (mode == 4 ? 1024u : (mode == 5 ? 512u : 256u)));
        memset(small, 0xd3, sizeof small);
        for (size_t i = 0; i < FIMG_INF_WSIZE / page_size; i++)
          pages[i] = small[i] + 16;
        fimg_inflate_init_pages(&inf, pages, page_size);
      }
      for (;;) {
        size_t n = next_chunk(p, &rs, idx++), used = 0;
        uint32_t prod = 0, start = inf.wpos;
        if (n > len - off) n = len - off;
        /* small output limits exercise suspension inside matches */
        r = fimg_inflate(&inf, data + off, n, &used,
                         p == 1 ? 100u : FIMG_INF_WSIZE, &prod);
        CHECK(used <= n);
        off += used;
        for (uint32_t i = 0; i < prod; i++) {
          crc ^= *fimg_window_ptr(&inf, (start + i) & FIMG_INF_WMASK);
          for (int k = 0; k < 8; k++)
            crc = (crc >> 1) ^ (0xedb88320u & (0u - (crc & 1u)));
        }
        total += prod;
        if (r < 0 || r == FIMG_INF_DONE) break;
        if (r == FIMG_INF_NEED_INPUT && off == len) break;
      }
      crc = ~crc;
      if (strcmp(kind, "ok") == 0) {
        unsigned long el = strtoul(a1, NULL, 10), ec = strtoul(a2, NULL, 16);
        CHECK_MSG(r == FIMG_INF_DONE && total == el && crc == ec,
                  "%s p%d r=%d total=%u", file, p, r, total);
        CHECK_MSG(off == len, "%s: %zu trailing bytes", file, len - off);
      } else if (strcmp(kind, "trunc") == 0) {
        CHECK_MSG(r == FIMG_INF_NEED_INPUT, "%s r=%d", file, r);
      } else {
        static const char *names[] = {"",      "header", "dict",
                                      "block", "stored", "tree",
                                      "code",  "dist",   "adler"};
        int want = 0;
        for (int i = 1; i < 9; i++)
          if (strcmp(a1, names[i]) == 0) want = -i;
        CHECK_MSG(want != 0 && r == want, "%s p%d: got %d want %s", file, p, r,
                  a1);
      }
      if (mode == 1) {
        for (size_t page = 0; page < 2; page++) {
          for (size_t i = 0; i < 16; i++) {
            CHECK(paged[page][i] == 0xd3);
            CHECK(paged[page][16 + FIMG_INF_PAGE_SIZE + i] == 0xd3);
          }
        }
      }
      if (mode >= 2) {
        uint32_t page_size =
            mode == 2
                ? 2048u
                : (mode == 3 ? 4096u
                             : (mode == 4 ? 1024u : (mode == 5 ? 512u : 256u)));
        for (size_t page = 0; page < FIMG_INF_WSIZE / page_size; page++) {
          for (size_t i = 0; i < 16; i++) {
            CHECK(small[page][i] == 0xd3);
            CHECK(small[page][16 + page_size + i] == 0xd3);
          }
        }
      }
    }
  }
  free(data);
}

/* Reference binarization: same box filter, global threshold 128. */
static void check_qr(const char *dir, const char *name, const result_t *r,
                     const char *mfile, long min_permille) {
  char path[512];
  const fimg_info_t *in = &r->info;
  const uint32_t f = in->scale, sw = in->src_width, sh = in->src_height;
  uint32_t agree = 0, total = 0, mod_bad = 0, mod_total = 0;
  size_t mlen;
  uint8_t *m;
  unsigned ox, oy, mpx, n;
  int consumed = 0;

  for (uint32_t oy2 = 0; oy2 < in->out_height; oy2++)
    for (uint32_t ox2 = 0; ox2 < in->out_width; ox2++) {
      uint32_t sum = 0, cnt = 0, ref, got;
      for (uint32_t y = oy2 * f; y < oy2 * f + f && y < sh; y++)
        for (uint32_t x = ox2 * f; x < ox2 * f + f && x < sw; x++) {
          sum += r->luma[(size_t)y * sw + x];
          cnt++;
        }
      ref = (sum + cnt / 2) / cnt;
      if (ref >= 104u && ref < 152u)
        continue; /* edge pixel: no well-defined reference */
      got = (r->bitmap[oy2 * in->stride + ox2 / 8] >> (7 - ox2 % 8)) & 1u;
      agree += (ref < 128u) == got;
      total++;
    }
  snprintf(path, sizeof path, "%s/%s", dir, mfile);
  m = read_file(path, &mlen);
  CHECK_MSG(m != NULL, "%s", path);
  if (m == NULL) return;
  m[mlen] = 0;
  CHECK(sscanf((const char *)m, "QR %u %u %u %u%n", &ox, &oy, &mpx, &n,
               &consumed) == 4);
  {
    const char *p = (const char *)m + consumed;
    for (unsigned my = 0; my < n; my++) {
      while (*p == '\n' || *p == '\r') p++;
      for (unsigned mx = 0; mx < n; mx++, p++) {
        uint32_t cx = (ox + mx * mpx + mpx / 2) / f,
                 cy = (oy + my * mpx + mpx / 2) / f;
        uint32_t got =
            (r->bitmap[cy * in->stride + cx / 8] >> (7 - cx % 8)) & 1u;
        mod_bad += got != (uint32_t)(*p == '1');
        mod_total++;
      }
    }
  }
  printf(
      "  qr %-28s %4ux%-4u /%u -> %ux%u win %u: pixel agreement %.2f%%, module "
      "errors %u/%u\n",
      name, sw, sh, f, in->out_width, in->out_height, in->window,
      100.0 * agree / total, mod_bad, mod_total);
  CHECK_MSG((long)(1000.0 * agree / total) >= min_permille,
            "%s agreement %.1f permille", name, 1000.0 * agree / total);
  CHECK_MSG(mod_bad == 0, "%s: %u module errors", name, mod_bad);
  free(m);
}

int main(int argc, char **argv) {
  const char *dir = argc > 1 ? argv[1] : FIMG_VECTORS_DIR;
  char path[512], line[1024];
  FILE *mf;
  int nvec = 0;
  int max_jpeg_diff = 0;
  fimg_config_t cfg, small;

  fimg_config_default(&cfg);
  fimg_config_default(&small);
  small.max_out_width = 100;
  small.max_out_height = 90;
  small.max_out_pixels = 7000;

  snprintf(path, sizeof path, "%s/manifest.txt", dir);
  mf = fopen(path, "r");
  if (mf == NULL) {
    fprintf(stderr, "cannot open %s\n", path);
    return 2;
  }
  while (fgets(line, sizeof line, mf)) {
    char kind[16], file[256], a[4][256];
    size_t len;
    uint8_t *data;
    result_t r;
    int n, want, strict;
    fimg_config_t c;

    if (line[0] == '#' || line[0] == '\n') continue;
    memset(a, 0, sizeof a);
    n = sscanf(line, "%15s %255s %255s %255s %255s %255s", kind, file, a[0],
               a[1], a[2], a[3]);
    if (n < 3) continue;
    nvec++;
    if (strcmp(kind, "zlib") == 0) {
      run_zlib(dir, file, a[0], a[1], a[2]);
      continue;
    }
    snprintf(path, sizeof path, "%s/%s", dir, file);
    data = read_file(path, &len);
    CHECK_MSG(data != NULL, "%s", path);
    if (data == NULL) continue;
    want = status_from_name(a[0]);
    CHECK_MSG(want >= 0, "unknown status %s", a[0]);
    strict = strstr(line, " strict") != NULL;
    c = cfg;
    if (strict) c.flags |= FIMG_FLAG_STRICT_TRAILER;

    decode_all(file, data, len, &c, &r);
    CHECK_MSG((int)r.st == want, "%s: status %s, expected %s", file,
              fimg_status_name(r.st), a[0]);
    CHECK(fimg_status_category(r.st) ==
          fimg_status_category((fimg_status_t)want));

    if (r.st == FIMG_OK && strcmp(kind, "luma") == 0) {
      uint32_t w, h;
      uint8_t *ref = read_pgm(
          (snprintf(path, sizeof path, "%s/%s", dir, a[2]), path), &w, &h);
      int tol = atoi(a[1]), maxd = 0;
      uint32_t ndiff = 0;
      CHECK_MSG(ref != NULL, "%s", a[2]);
      if (ref != NULL) {
        CHECK(w == r.info.src_width && h == r.info.src_height);
        if (w == r.info.src_width && h == r.info.src_height) {
          for (size_t i = 0; i < (size_t)w * h; i++) {
            int d = abs((int)ref[i] - (int)r.luma[i]);
            if (d > maxd) maxd = d;
            ndiff += d != 0;
          }
        }
        CHECK_MSG(maxd <= tol, "%s: max luma diff %d (%u px differ)", file,
                  maxd, ndiff);
        if (tol > 0 && maxd > max_jpeg_diff) max_jpeg_diff = maxd;
        free(ref);
      }
    } else if (r.st == FIMG_OK && strcmp(kind, "lumacrc") == 0) {
      CHECK(r.info.src_width == (uint32_t)atoi(a[1]) &&
            r.info.src_height == (uint32_t)atoi(a[2]));
      CHECK_MSG(r.luma_crc == (uint32_t)strtoul(a[3], NULL, 16), "%s luma crc",
                file);
    } else if (r.st == FIMG_OK && strcmp(kind, "qr") == 0) {
      check_qr(dir, file, &r, a[1], atol(a[2]));
    }
    /* a heavily downscaled decode must give the same status and luma */
    {
      result_t s;
      c = small;
      if (strict) c.flags |= FIMG_FLAG_STRICT_TRAILER;
      decode(data, len, 4, &c, &s, 0);
      {
        result_t segmented;
        decode(data, len, 4, &c, &segmented, 1);
        CHECK_MSG(segmented.st == s.st &&
                      memcmp(&segmented.info, &s.info, sizeof s.info) == 0 &&
                      memcmp(segmented.luma, s.luma,
                             (size_t)FIMG_MAX_DIM * FIMG_MAX_DIM) == 0 &&
                      memcmp(segmented.bitmap, s.bitmap, s.bitmap_size) == 0,
                  "%s: small scattered differs", file);
        free_result(&segmented);
      }
      CHECK_MSG(s.st == r.st, "%s: small config status %s", file,
                fimg_status_name(s.st));
      if (s.st == FIMG_OK) {
        CHECK(s.luma_crc == r.luma_crc);
        CHECK(s.info.out_width <= 100 && s.info.out_height <= 90 &&
              s.info.out_width * s.info.out_height <= 7000);
        CHECK(s.info.out_width ==
              (s.info.src_width + s.info.scale - 1) / s.info.scale);
      }
      free_result(&s);
    }
    /* Large PNGs inflate through both 16 KiB pages and wrap the full 32 KiB
       history many times. Native device limits and full-width output also
       exercise the binarizer ring across its scattered page boundaries. */
    if (strcmp(file, "qr_backup_1024.png") == 0 ||
        strcmp(file, "qr_backup_1024_q70.jpg") == 0 ||
        strcmp(file, "png_1024_gray1.png") == 0) {
      static const uint16_t dimensions[] = {256, 320, 384, 1024};
      for (size_t i = 0; i < sizeof dimensions / sizeof dimensions[0]; i++) {
        result_t limited;
        c = cfg;
        c.max_out_width = c.max_out_height = dimensions[i];
        decode_all(file, data, len, &c, &limited);
        CHECK(limited.st == r.st);
        if (limited.st == FIMG_OK) {
          CHECK(limited.luma_crc == r.luma_crc);
          CHECK(limited.info.out_width <= dimensions[i] &&
                limited.info.out_height <= dimensions[i]);
        }
        free_result(&limited);
      }
    }
    free_result(&r);
    free(data);
  }
  fclose(mf);
  printf("vectors: %d, max JPEG luma diff vs libjpeg: %d\n", nvec,
         max_jpeg_diff);
  printf("host timing: 1024x1024 JPEG %.1f ms, 1024x1024 PNG %.1f ms\n",
         g_time_jpeg_1024 * 1e3, g_time_png_1024 * 1e3);
  CHECK(nvec > 200);
  return test_summary("fimg_vectors");
}
